@file:Suppress("unused")import org.gradle.kotlin.dsl.DependencyHandlerScopeimport org.gradle.kotlin.dsl.PluginDependenciesSpecScopeimport utils.BomScopeinfix fun PluginDependenciesSpecScope.notate(plugin: Plugin) {	id(plugin.project).version(plugin.version).apply(false)}infix fun PluginDependenciesSpecScope.apply(plugin: Plugin) {	id(plugin.project).apply(true)}infix fun DependencyHandlerScope.dependency(dependency: Dependency) {	add("implementation", dependency.dependencyNotation)}infix fun DependencyHandlerScope.exportDependency(dependency: Dependency) {	add("api", dependency.dependencyNotation)}fun DependencyHandlerScope.bom(dependency: Dependency, scopeBlock: BomScope.() -> Unit) {	add("implementation",platform(dependency.dependencyNotation))	val scope = BomScope(this)	scopeBlock(scope)}